onSubmit:
{{
  (async () => {
    // --- VERROU ANTI-DOUBLE SCAN ---
    if (appsmith.store.isScanning) {
      console.log("Scan ignoré : un traitement est déjà en cours.");
      return;
    }
    await storeValue('isScanning', true);
    // ---------------------------------

    try {
      const code = inp_scan_article.text?.trim();
      const qte = inp_quantite.text !== "" && !isNaN(inp_quantite.text) ? Number(inp_quantite.text) : 1;

      if (!code) {
        await storeValue('isScanning', false);
        return;
      }

      // 1. Recherche de l'article dans la base (Code-barres, Réf ou ID)
      const articles = Get_Tous_Articles.data || [];
      const art = articles.find(a => 
        (a.Code_Barre && a.Code_Barre.toLowerCase() === code.toLowerCase()) ||
        (a.Ref_Fournisseur && a.Ref_Fournisseur.toLowerCase() === code.toLowerCase()) ||
        (a.ID_Article && a.ID_Article.toLowerCase() === code.toLowerCase())
      );

      if (!art) {
        showAlert('❌ Article non reconnu pour le code : ' + code, 'error');
        resetWidget('inp_scan_article', true);
        storeValue('forceFocus', Date.now()); // <--- FORCER L'AUTOFOCUS
        await storeValue('isScanning', false); // Libérer le verrou
        return;
      }

      // 2. Enregistrement en base de données
      await Valider_Scan_Inv.run({
        idArticle: art.ID_Article,
        quantite: qte
      });

      // 3. Message de succès
      showAlert('✅ ' + art.Designation + ' (Qté : ' + qte + ')', 'success');

      // 4. Nettoyage immédiat pour la douchette
      resetWidget('inp_scan_article', true);
      resetWidget('inp_quantite', true);

      // <--- FORCER L'AUTOFOCUS IMMÉDIATEMENT APRÈS LE NETTOYAGE
      storeValue('forceFocus', Date.now());

      // 5. Rafraîchissement des tableaux en arrière-plan
      Get_Derniers_Scans.run();
      Get_Non_Scannes.run();

    } catch (err) {
      showAlert('Erreur lors du scan : ' + err.message, 'error');
      storeValue('forceFocus', Date.now()); // <--- FORCER L'AUTOFOCUS EN CAS D'ERREUR AUSSI
    } finally {
      // --- LIBÉRER LE VERROU DANS TOUS LES CAS ---
      await storeValue('isScanning', false);
    }
  })()
}}
